type EventHandler = (payload: any) => void | Promise<void>;

export class EventBus {
  private subscribers: Map<string, Set<EventHandler>> = new Map();

  subscribe(eventName: string, handler: EventHandler) {
    if (!this.subscribers.has(eventName)) this.subscribers.set(eventName, new Set());
    this.subscribers.get(eventName)!.add(handler);
    return () => this.subscribers.get(eventName)!.delete(handler);
  }

  async publish(eventName: string, payload: any) {
    const handlers = this.subscribers.get(eventName);
    if (!handlers) return;
    for (const h of Array.from(handlers)) {
      try {
        await h(payload);
      } catch (err) {
        console.error(`Error handling event ${eventName}:`, err);
      }
    }
  }
}

import { randomUUID } from 'crypto';

export type User = {
  id: string;
  name: string;
  email: string;
};

export class UserService {
  private users: Map<string, User> = new Map();

  createUser(name: string, email: string): User {
    const id = randomUUID();
    const user: User = { id, name, email };
    this.users.set(id, user);
    return user;
  }

  getUser(id: string): User | undefined {
    return this.users.get(id);
  }

  updateUser(id: string, data: Partial<Omit<User, 'id'>>): User | undefined {
    const existing = this.users.get(id);
    if (!existing) return undefined;
    const updated = { ...existing, ...data };
    this.users.set(id, updated);
    return updated;
  }

  deleteUser(id: string): boolean {
    return this.users.delete(id);
  }

  listUsers(): User[] {
    return Array.from(this.users.values());
  }
}

import { randomUUID } from 'crypto';

export type Project = {
  id: string;
  name: string;
  description?: string;
  members: string[]; // user IDs
};

export class ProjectService {
  private projects: Map<string, Project> = new Map();

  createProject(name: string, description?: string): Project {
    const id = randomUUID();
    const p: Project = { id, name, description, members: [] };
    this.projects.set(id, p);
    return p;
  }

  getProject(id: string): Project | undefined {
    return this.projects.get(id);
  }

  updateProject(id: string, data: Partial<Omit<Project, 'id' | 'members'>>): Project | undefined {
    const existing = this.projects.get(id);
    if (!existing) return undefined;
    const updated = { ...existing, ...data };
    this.projects.set(id, updated);
    return updated;
  }

  deleteProject(id: string): boolean {
    return this.projects.delete(id);
  }

  addMember(projectId: string, userId: string): boolean {
    const p = this.projects.get(projectId);
    if (!p) return false;
    if (!p.members.includes(userId)) p.members.push(userId);
    return true;
  }

  removeMember(projectId: string, userId: string): boolean {
    const p = this.projects.get(projectId);
    if (!p) return false;
    p.members = p.members.filter((m) => m !== userId);
    return true;
  }

  listProjects(): Project[] {
    return Array.from(this.projects.values());
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export type Task = {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  assignee?: string; // user id
  projectId: string;
};

export class TaskService {
  private tasks: Map<string, Task> = new Map();
  constructor(private eventBus: EventBus) {}

  createTask(title: string, projectId: string, description?: string): Task {
    const id = randomUUID();
    const task: Task = { id, title, description, status: 'todo', projectId };
    this.tasks.set(id, task);
    this.eventBus.publish('task.created', { task });
    return task;
  }

  getTask(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  updateTask(id: string, data: Partial<Omit<Task, 'id' | 'projectId'>>): Task | undefined {
    const existing = this.tasks.get(id);
    if (!existing) return undefined;
    const updated = { ...existing, ...data };
    this.tasks.set(id, updated);
    this.eventBus.publish('task.updated', { task: updated });
    return updated;
  }

  deleteTask(id: string): boolean {
    const t = this.tasks.get(id);
    if (!t) return false;
    this.tasks.delete(id);
    this.eventBus.publish('task.deleted', { task: t });
    return true;
  }

  listTasks(filter?: { projectId?: string }): Task[] {
    let res = Array.from(this.tasks.values());
    if (filter?.projectId) res = res.filter((t) => t.projectId === filter.projectId);
    return res;
  }

  setStatus(id: string, status: TaskStatus): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    // validate transition
    const order: TaskStatus[] = ['todo', 'in-progress', 'done'];
    const from = order.indexOf(task.status);
    const to = order.indexOf(status);
    if (to === -1) return undefined;
    if (to < from) throw new Error(`Invalid status transition from ${task.status} to ${status}`);
    task.status = status;
    this.tasks.set(id, task);
    this.eventBus.publish('task.status_changed', { task });
    return task;
  }

  assign(id: string, userId: string): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    task.assignee = userId;
    this.tasks.set(id, task);
    this.eventBus.publish('task.assigned', { task });
    return task;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export type Comment = {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO
};

export class CommentService {
  private comments: Map<string, Comment> = new Map();
  constructor(private eventBus: EventBus) {}

  addComment(taskId: string, authorId: string, body: string): Comment {
    const id = randomUUID();
    const c: Comment = { id, taskId, authorId, body, createdAt: new Date().toISOString() };
    this.comments.set(id, c);
    this.eventBus.publish('comment.added', { comment: c });
    return c;
  }

  getComment(id: string): Comment | undefined {
    return this.comments.get(id);
  }

  deleteComment(id: string): boolean {
    const c = this.comments.get(id);
    if (!c) return false;
    this.comments.delete(id);
    this.eventBus.publish('comment.deleted', { comment: c });
    return true;
  }

  listComments(filter?: { taskId?: string }): Comment[] {
    let res = Array.from(this.comments.values());
    if (filter?.taskId) res = res.filter((c) => c.taskId === filter.taskId);
    return res;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export type Notification = {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  timestamp: string;
};

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor(private eventBus: EventBus) {
    // subscribe to events
    this.eventBus.subscribe('task.assigned', async (payload) => this.onTaskAssigned(payload));
    this.eventBus.subscribe('comment.added', async (payload) => this.onCommentAdded(payload));
    this.eventBus.subscribe('task.status_changed', async (payload) => this.onStatusChanged(payload));
  }

  private createNotification(userId: string, message: string) {
    const id = randomUUID();
    const n: Notification = { id, userId, message, read: false, timestamp: new Date().toISOString() };
    this.notifications.set(id, n);
    return n;
  }

  private async onTaskAssigned(payload: any) {
    const task = payload.task;
    if (!task || !task.assignee) return;
    this.createNotification(task.assignee, `You were assigned task ${task.title} (id=${task.id})`);
  }

  private async onCommentAdded(payload: any) {
    const comment = payload.comment;
    if (!comment) return;
    // Notify the assignee of the task if present. The payload may not include task assignee, so event origin should include it.
    // To keep services decoupled, assume comment.payload may include task info. If not, we still create a generic notification for the author.
    if (payload.task && payload.task.assignee) {
      const aid = payload.task.assignee;
      this.createNotification(aid, `A new comment was added to task ${payload.task.title} (id=${payload.task.id})`);
    }
  }

  private async onStatusChanged(payload: any) {
    const task = payload.task;
    if (!task) return;
    if (task.assignee) this.createNotification(task.assignee, `Status of task ${task.title} changed to ${task.status}`);
  }

  listNotifications(filter?: { userId?: string }): Notification[] {
    let res = Array.from(this.notifications.values());
    if (filter?.userId) res = res.filter((n) => n.userId === filter.userId);
    return res.sort((a, b) => a.timestamp.localeCompare(b.timestamp));
  }

  markRead(id: string): Notification | undefined {
    const n = this.notifications.get(id);
    if (!n) return undefined;
    n.read = true;
    this.notifications.set(id, n);
    return n;
  }
}

import { createServer, IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';
import { EventBus } from './event-bus';

function parseJSON(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => (body += chunk));
    req.on('end', () => {
      if (!body) return resolve(undefined);
      try {
        resolve(JSON.parse(body));
      } catch (err) {
        reject(err);
      }
    });
    req.on('error', reject);
  });
}

function sendJSON(res: ServerResponse, code: number, payload: any) {
  const s = JSON.stringify(payload);
  res.writeHead(code, { 'Content-Type': 'application/json' });
  res.end(s);
}

export function createServerWithServices(port: number, services: {
  eventBus: EventBus;
  users: UserService;
  projects: ProjectService;
  tasks: TaskService;
  comments: CommentService;
  notifications: NotificationService;
}) {
  const server = createServer(async (req, res) => {
    const url = new URL(req.url || '', `http://${req.headers.host}`);
    const parts = url.pathname.split('/').filter(Boolean);
    try {
      if (parts[0] === 'users') {
        if (req.method === 'GET' && parts.length === 1) {
          return sendJSON(res, 200, services.users.listUsers());
        }
        if (req.method === 'POST' && parts.length === 1) {
          const body = await parseJSON(req);
          if (!body?.name || !body?.email) return sendJSON(res, 400, { error: 'name and email required' });
          const u = services.users.createUser(body.name, body.email);
          return sendJSON(res, 201, u);
        }
        if (parts.length === 2) {
          const id = parts[1];
          if (req.method === 'GET') {
            const u = services.users.getUser(id);
            if (!u) return sendJSON(res, 404, { error: 'not found' });
            return sendJSON(res, 200, u);
          }
          if (req.method === 'PUT') {
            const body = await parseJSON(req);
            const u = services.users.updateUser(id, body || {});
            if (!u) return sendJSON(res, 404, { error: 'not found' });
            return sendJSON(res, 200, u);
          }
          if (req.method === 'DELETE') {
            const ok = services.users.deleteUser(id);
            return sendJSON(res, ok ? 200 : 404, ok ? { ok: true } : { error: 'not found' });
          }
        }
      } else if (parts[0] === 'projects') {
        if (req.method === 'GET' && parts.length === 1) {
          return sendJSON(res, 200, services.projects.listProjects());
        }
        if (req.method === 'POST' && parts.length === 1) {
          const body = await parseJSON(req);
          if (!body?.name) return sendJSON(res, 400, { error: 'name required' });
          const p = services.projects.createProject(body.name, body.description);
          return sendJSON(res, 201, p);
        }
        if (parts.length === 2) {
          const id = parts[1];
          if (req.method === 'GET') {
            const p = services.projects.getProject(id);
            if (!p) return sendJSON(res, 404, { error: 'not found' });
            return sendJSON(res, 200, p);
          }
          if (req.method === 'PUT') {
            const body = await parseJSON(req);
            const p = services.projects.updateProject(id, body || {});
            if (!p) return sendJSON(res, 404, { error: 'not found' });
            return sendJSON(res, 200, p);
          }
          if (req.method === 'DELETE') {
            const ok = services.projects.deleteProject(id);
            return sendJSON(res, ok ? 200 : 404, ok ? { ok: true } : { error: 'not found' });
          }
        }
        if (parts.length === 3 && parts[2] === 'members') {
          const id = parts[1];
          if (req.method === 'POST') {
            const body = await parseJSON(req);
            if (!body?.userId) return sendJSON(res, 400, { error: 'userId required' });
            const ok = services.projects.addMember(id, body.userId);
            return sendJSON(res, ok ? 200 : 404, ok ? { ok: true } : { error: 'not found' });
          }
          if (req.method === 'DELETE') {
            const body = await parseJSON(req);
            if (!body?.userId) return sendJSON(res, 400, { error: 'userId required' });
            const ok = services.projects.removeMember(id, body.userId);
            return sendJSON(res, ok ? 200 : 404, ok ? { ok: true } : { error: 'not found' });
          }
        }
      } else if (parts[0] === 'tasks') {
        if (req.method === 'GET' && parts.length === 1) {
          const pid = url.searchParams.get('projectId') || undefined;
          return sendJSON(res, 200, services.tasks.listTasks(pid ? { projectId: pid } : undefined));
        }
        if (req.method === 'POST' && parts.length === 1) {
          const body = await parseJSON(req);
          if (!body?.title || !body?.projectId) return sendJSON(res, 400, { error: 'title and projectId required' });
          const t = services.tasks.createTask(body.title, body.projectId, body.description);
          return sendJSON(res, 201, t);
        }
        if (parts.length === 2) {
          const id = parts[1];
          if (req.method === 'GET') {
            const t = services.tasks.getTask(id);
            if (!t) return sendJSON(res, 404, { error: 'not found' });
            return sendJSON(res, 200, t);
          }
          if (req.method === 'PUT') {
            const body = await parseJSON(req);
            const t = services.tasks.updateTask(id, body || {});
            if (!t) return sendJSON(res, 404, { error: 'not found' });
            return sendJSON(res, 200, t);
          }
          if (req.method === 'DELETE') {
            const ok = services.tasks.deleteTask(id);
            return sendJSON(res, ok ? 200 : 404, ok ? { ok: true } : { error: 'not found' });
          }
        }
        if (parts.length === 3 && parts[2] === 'status' && req.method === 'PUT') {
          const id = parts[1];
          const body = await parseJSON(req);
          if (!body?.status) return sendJSON(res, 400, { error: 'status required' });
          try {
            const t = services.tasks.setStatus(id, body.status);
            if (!t) return sendJSON(res, 404, { error: 'not found' });
            return sendJSON(res, 200, t);
          } catch (err: any) {
            return sendJSON(res, 400, { error: err.message });
          }
        }
        if (parts.length === 3 && parts[2] === 'assign' && req.method === 'PUT') {
          const id = parts[1];
          const body = await parseJSON(req);
          if (!body?.userId) return sendJSON(res, 400, { error: 'userId required' });
          const t = services.tasks.assign(id, body.userId);
          if (!t) return sendJSON(res, 404, { error: 'not found' });
          return sendJSON(res, 200, t);
        }
      } else if (parts[0] === 'comments') {
        if (req.method === 'GET' && parts.length === 1) {
          const tid = url.searchParams.get('taskId') || undefined;
          return sendJSON(res, 200, services.comments.listComments(tid ? { taskId: tid } : undefined));
        }
        if (req.method === 'POST' && parts.length === 1) {
          const body = await parseJSON(req);
          if (!body?.taskId || !body?.authorId || !body?.body) return sendJSON(res, 400, { error: 'taskId, authorId, body required' });
          // To allow NotificationService to notify task assignee, we can enrich event payload by looking up task here and passing it to comment service via event - but services should not call each other. Instead, we provide task info in the event by passing it as optional parameter when calling commentService.addComment? Simpler: after creating comment, also fetch task from tasks service and publish combined payload here.
          const comment = services.comments.addComment(body.taskId, body.authorId, body.body);
          // publish enriched event
          const task = services.tasks.getTask(body.taskId);
          services.eventBus.publish('comment.added', { comment, task });
          return sendJSON(res, 201, comment);
        }
        if (parts.length === 2) {
          const id = parts[1];
          if (req.method === 'GET') {
            const c = services.comments.getComment(id);
            if (!c) return sendJSON(res, 404, { error: 'not found' });
            return sendJSON(res, 200, c);
          }
          if (req.method === 'DELETE') {
            const ok = services.comments.deleteComment(id);
            return sendJSON(res, ok ? 200 : 404, ok ? { ok: true } : { error: 'not found' });
          }
        }
      } else if (parts[0] === 'notifications') {
        if (req.method === 'GET' && parts.length === 1) {
          const uid = url.searchParams.get('userId') || undefined;
          return sendJSON(res, 200, services.notifications.listNotifications(uid ? { userId: uid } : undefined));
        }
        if (parts.length === 3 && parts[2] === 'read' && req.method === 'PUT') {
          const id = parts[1];
          const n = services.notifications.markRead(id);
          if (!n) return sendJSON(res, 404, { error: 'not found' });
          return sendJSON(res, 200, n);
        }
      }

      sendJSON(res, 404, { error: 'not found' });
    } catch (err) {
      console.error(err);
      sendJSON(res, 500, { error: 'internal' });
    }
  });

  return {
    listen: (cb?: () => void) => server.listen(port, cb),
    close: (cb?: () => void) => server.close(cb),
  };
}

import { EventBus } from './event-bus';
